style.css:
@-moz-document domain("lichess.org") {
/* Хэллоуинская шахматная доска Lichess */
  .lichess_board {
    border: 2px solid #444 !important;
    box-shadow: 0 0 15px rgba(255, 165, 0, 0.3) !important;
  }

  /* Доска */
  .is2d .cg-board {
    background-image: url('https://images.chesscomfiles.com/chess-themes/boards/halloween/220.png') !important;
  }

  /* Фигуры */
  piece.pawn.white { background-position: 0% 83.33333333333333% !important; }
  piece.knight.white { background-position: 0% 66.66666666666667% !important; }
  piece.bishop.white { background-position: 0% 50% !important; }
  piece.rook.white { background-position: 0% 33.333333333333336% !important; }
  piece.queen.white { background-position: 0% 16.666666666666668% !important; }
  piece.king.white { background-position: 0% 0% !important; }

  piece.pawn.black { background-position: 100% 83.33333333333333% !important; }
  piece.knight.black { background-position: 100% 66.66666666666667% !important; }
  piece.bishop.black { background-position: 100% 50% !important; }
  piece.rook.black { background-position: 100% 33.333333333333336% !important; }
  piece.queen.black { background-position: 100% 16.666666666666668% !important; }
  piece.king.black { background-position: 100% 0% !important; }

  /* Базовый стиль для всех фигур */
  piece {
    background-image: url('https://images.chesscomfiles.com/chess-themes/pieces/halloween/220.png') !important;
    background-size: 600% 600% !important;
  }

  /* Подсветка ходов */
  .move-dest {
    background: radial-gradient(rgba(255, 165, 0, 0.4) 19%, rgba(255, 165, 0, 0) 20%) !important;
  }

  .last-move {
    background-color: rgba(255, 140, 0, 0.4) !important;
  }

  .selected {
    background-color: rgba(255, 69, 0, 0.6) !important;
  }

  /* Координаты */
  cg-coords {
    color: #fff !important;
    text-shadow: 0 1px 2px rgba(0,0,0,0.8) !important;
    font-weight: bold !important;
  }
}
